import Link from "next/link";
import {
  Activity, AlertTriangle, ArrowRight, BarChart3, Bell, BriefcaseBusiness,
  Building2, CalendarDays, CheckCircle2, ChevronDown,
  Clock3, Database, Download, FileCheck2, FileText, Files, Filter,
  Globe2, Inbox, Link2, Mail, MessageSquare, MoreHorizontal, Pause, Phone,
  Play, Plus, RefreshCw, Search, Send, Settings, ShieldCheck, Sparkles,
  Target, UserCheck, UserRound, Users, Zap,
} from "lucide-react";
import type { ComponentType, ReactNode } from "react";
import s from "./lead-acquisition.module.css";

type Icon = ComponentType<{ size?: number }>;
type Tone = "green"|"orange"|"red"|"blue"|"gray"|"teal"|"purple";
type Row = ReactNode[];
const portraits=["/images/articles/elena-rossi.png","/images/articles/arjun-mehta.png","/images/articles/marcus-chen.png","/images/articles/daniel-kim.png"];

function Button({children,primary=false,href="#"}:{children:ReactNode;primary?:boolean;href?:string}){return <Link href={href} className={`${s.btn} ${primary?s.primary:""}`}>{children}</Link>}
function Badge({children,tone="purple"}:{children:ReactNode;tone?:Tone}){return <span className={`${s.badge} ${tone==="purple"?"":s[tone]}`}>{children}</span>}
function Logo({text}:{text:string}){return <span className={s.logo}>{text}</span>}
function Avatar({i=0}:{i?:number}){return <img className={s.avatar} src={portraits[i%portraits.length]} alt=""/>}
function Stack({title,sub}:{title:ReactNode;sub?:ReactNode}){return <span className={s.stack}><b>{title}</b>{sub&&<small>{sub}</small>}</span>}
function Header({title,subtitle,action="Add New",icon=Plus}:{title:string;subtitle:string;action?:string;icon?:Icon}){const I=icon;return <header className={s.head}><div><h1>{title}</h1><p>{subtitle}</p></div><div className={s.headTools}><label className={s.search}><Search size={15}/><input placeholder={`Search ${title.toLowerCase()}...`}/><kbd>⌘ K</kbd></label><Button primary><I size={14}/>{action}<ChevronDown size={12}/></Button><Bell size={19}/></div></header>}
function Stats({items}:{items:Array<[string,string,Icon,string?]>}){return <section className={s.stats} style={{"--count":Math.min(items.length,8)} as React.CSSProperties}>{items.map(([label,value,I,note])=><article className={s.stat} key={label}><div><I size={17}/></div><p><small>{label}</small><b>{value}</b><em>{note||"This month"}</em></p></article>)}</section>}
function Tabs({items}:{items:Array<[string,string?]>}){return <nav className={s.tabs}>{items.map(([label,count],i)=><button key={label} className={i===0?s.active:""}>{label}{count&&<em>{count}</em>}</button>)}</nav>}
function Filters({items=["All Industries","All Regions","All Owners","All Statuses"]}:{items?:string[]}){return <div className={s.filters}><label><Search size={13}/><input placeholder="Search records..."/></label>{items.map(x=><button key={x}>{x}<ChevronDown size={12}/></button>)}<i className={s.filterSpacer}/><Button><Filter size={13}/>More Filters</Button></div>}
function Table({headers,rows,cols="1.6fr 1fr 1fr .8fr .8fr .8fr .8fr .8fr .55fr"}:{headers:string[];rows:Row[];cols?:string}){return <div className={s.table}><div className={s.tableHead} style={{"--cols":cols} as React.CSSProperties}>{headers.map(h=><span key={h}>{h}</span>)}</div>{rows.map((row,ri)=><article className={`${s.row} ${ri===0?s.selected:""}`} style={{"--cols":cols} as React.CSSProperties} key={ri}>{row.map((cell,ci)=><span className={s.cell} key={ci}>{cell}</span>)}</article>)}</div>}
function Pager({count="10",total="128"}:{count?:string;total?:string}){return <footer className={s.pager}><span>Showing 1 to {count} of {total} records</span><div className={s.pages}>{["1","2","3","4","5","›"].map(x=><button key={x}>{x}</button>)}</div><span>Rows per page&nbsp; <b>10⌄</b></span></footer>}
function Panel({title,children,action}:{title:string;children:ReactNode;action?:string}){return <section className={s.panel}><header><h2>{title}</h2>{action&&<a>{action} →</a>}</header><div className={s.panelBody}>{children}</div></section>}
function MetricGrid({items}:{items:Array<[string,string]>}){return <div className={s.metricGrid}>{items.map(x=><article key={x[0]}><small>{x[0]}</small><b>{x[1]}</b></article>)}</div>}
function Quick({items}:{items:Array<[string,Icon,string?]>}){return <div className={s.quick}>{items.map(([x,I,href])=><Link href={href||"#"} key={x}><I size={18}/><span>{x}</span></Link>)}</div>}
function Person({name,role,i=0}:{name:string;role?:string;i?:number}){return <span className={s.cell}><Avatar i={i}/><Stack title={name} sub={role}/></span>}
function Progress({value}:{value:number}){return <div className={s.progress}><i style={{width:`${value}%`}}/></div>}
function Donut({value}:{value:string}){return <div className={s.donut} data-value={value}/>}
function RailList({items}:{items:Array<[string,string,string?]>}){return <div className={s.list}>{items.map(([a,b,c])=><article key={a}><span><b>{a}</b><small>{b}</small></span>{c&&<time>{c}</time>}</article>)}</div>}
function Workflow({steps,current=3}:{steps:string[];current?:number}){return <div className={s.workflow}>{steps.map((x,i)=><span key={x} className={i<current?s.done:i===current?s.current:""}><b>{x}</b><small>{i<current?"Completed":i===current?"Current":"Upcoming"}</small></span>)}</div>}
function DetailHeader({initials,title,subtitle,badge="Qualified",facts}:{initials:string;title:string;subtitle:string;badge?:string;facts:Array<[string,string]>}){return <><section className={s.detailHero}><Logo text={initials}/><div><h1>{title} <Badge tone="green">{badge}</Badge></h1><p>{subtitle}</p></div><div className={s.headTools}><label className={s.search}><Search size={14}/><input placeholder="Search this record..."/></label><Button primary><Send size={13}/>Start Outreach</Button><Button><MoreHorizontal size={14}/></Button></div></section><div className={s.facts}>{facts.map(x=><div key={x[0]}><small>{x[0]}</small><b>{x[1]}</b></div>)}</div></>}

